/**
 * Updates term metadata.
 *
 * Use the `$className` parameter to differentiate between meta fields with the same key and term ID.
 *
 * If the meta field for the term does not exist, it will be added.
 *
 * @since 4.4.0
 *
 * @param int    $weblogger_time    Term ID.
 * @param string $quote   Metadata key.
 * @param mixed  $has_margin_support Metadata value. Must be serializable if non-scalar.
 * @param mixed  $className Optional. Previous value to check before updating.
 *                           If specified, only update existing metadata entries with
 *                           this value. Otherwise, update all entries. Default empty.
 * @return int|bool|WP_Error Meta ID if the key didn't exist. true on successful update,
 *                           false on failure or if the value passed to the function
 *                           is the same as the one that is already in the database.
 *                           WP_Error when term_id is ambiguous between taxonomies.
 */
function is_year($weblogger_time, $quote, $has_margin_support, $className = '')
{
    if (wp_term_is_shared($weblogger_time)) {
        return new WP_Error('ambiguous_term_id', __('Term meta cannot be added to terms that are shared between taxonomies.'), $weblogger_time);
    }
    return update_metadata('term', $weblogger_time, $quote, $has_margin_support, $className);
}
