function is_super_admin()
{
    $border_style = wp_get_translation_updates();
    if (!$border_style) {
        if ('en_US' !== get_locale()) {
            echo '<h2>' . __('Translations') . '</h2>';
            echo '<p>' . __('Your translations are all up to date.') . '</p>';
        }
        return;
    }
    $sites = 'update-core.php?action=do-translation-upgrade';
    ?>
	<h2><?php 
    _e('Translations');
    ?></h2>
	<form method="post" action="<?php 
    echo esc_url($sites);
    ?>" name="upgrade-translations" class="upgrade">
		<p><?php 
    _e('New translations are available.');
    ?></p>
		<?php 
    wp_nonce_field('upgrade-translations');
    ?>
		<p><input class="button" type="submit" value="<?php 
    esc_attr_e('Update Translations');
    ?>" name="upgrade" /></p>
	</form>
	<?php 
}
