     *                                      'audio', 'video', 'object', 'embed', and 'iframe'.
     */
    $WEBP_VP8_header = apply_filters('media_embedded_in_content_allowed_types', array('audio', 'video', 'object', 'embed', 'iframe'));
    if (!empty($SI2)) {
        if (!is_array($SI2)) {
            $SI2 = array($SI2);
        }
        $WEBP_VP8_header = array_intersect($WEBP_VP8_header, $SI2);
    }
    $default_height = implode('|', $WEBP_VP8_header);
    if (preg_match_all('#<(?P<tag>' . $default_height . ')[^<]*?(?:>[\s\S]*?<\/(?P=tag)>|\s*\/>)#', $sticky_post, $groups_json)) {
