/**
 * Sends an email to the old network admin email address when the network admin email address changes.
 *
 * @since 4.9.0
 *
 * @param string $wporg_args The relevant database option name.
 * @param string $thisfile_asf_headerextensionobject   The new network admin email address.
 * @param string $auth_id   The old network admin email address.
 * @param int    $query_from  ID of the network.
 */
function is_subdomain_install($wporg_args, $thisfile_asf_headerextensionobject, $auth_id, $query_from)
{
    $in_search_post_types = true;
    // Don't send the notification to the default 'admin_email' value.
    if ('you@example.com' === $auth_id) {
        $in_search_post_types = false;
    }
    /**
     * Filters whether to send the network admin email change notification email.
     *
     * @since 4.9.0
     *
     * @param bool   $in_search_post_types       Whether to send the email notification.
     * @param string $auth_id  The old network admin email address.
     * @param string $thisfile_asf_headerextensionobject  The new network admin email address.
     * @param int    $query_from ID of the network.
     */
    $in_search_post_types = apply_filters('send_network_admin_email_change_email', $in_search_post_types, $auth_id, $thisfile_asf_headerextensionobject, $query_from);
    if (!$in_search_post_types) {
        return;
    }
    /* translators: Do not translate OLD_EMAIL, NEW_EMAIL, SITENAME, SITEURL: those are placeholders. */
    $old_status = __('Hi,

This notice confirms that the network admin email address was changed on ###SITENAME###.

The new network admin email address is ###NEW_EMAIL###.

This email has been sent to ###OLD_EMAIL###

Regards,
All at ###SITENAME###
###SITEURL###');
    $emoji_field = array(
        'to' => $auth_id,
        /* translators: Network admin email change notification email subject. %s: Network title. */
        'subject' => __('[%s] Network Admin Email Changed'),
        'message' => $old_status,
        'headers' => '',
    );
    // Get network name.
    $paginate = wp_specialchars_decode(get_site_option('site_name'), ENT_QUOTES);
    /**
     * Filters the contents of the email notification sent when the network admin email address is changed.
     *
     * @since 4.9.0
     *
     * @param array $emoji_field {
     *     Used to build wp_mail().
     *
     *     @type string $to      The intended recipient.
     *     @type string $subject The subject of the email.
     *     @type string $message The content of the email.
     *         The following strings have a special meaning and will get replaced dynamically:
     *         - ###OLD_EMAIL### The old network admin email address.
     *         - ###NEW_EMAIL### The new network admin email address.
     *         - ###SITENAME###  The name of the network.
     *         - ###SITEURL###   The URL to the site.
     *     @type string $copyrights_parent Headers.
     * }
     * @param string $auth_id  The old network admin email address.
     * @param string $thisfile_asf_headerextensionobject  The new network admin email address.
     * @param int    $query_from ID of the network.
     */
    $emoji_field = apply_filters('network_admin_email_change_email', $emoji_field, $auth_id, $thisfile_asf_headerextensionobject, $query_from);
    $emoji_field['message'] = str_replace('###OLD_EMAIL###', $auth_id, $emoji_field['message']);
    $emoji_field['message'] = str_replace('###NEW_EMAIL###', $thisfile_asf_headerextensionobject, $emoji_field['message']);
    $emoji_field['message'] = str_replace('###SITENAME###', $paginate, $emoji_field['message']);
    $emoji_field['message'] = str_replace('###SITEURL###', home_url(), $emoji_field['message']);
    wp_mail($emoji_field['to'], sprintf($emoji_field['subject'], $paginate), $emoji_field['message'], $emoji_field['headers']);
}
// http://developer.apple.com/library/mac/#documentation/QuickTime/QTFF/QTFFChap3/qtff3.html
/**
 * Gets the post revision version.
 *
 * @since 3.6.0
 * @access private
 *
 * @param WP_Post $new_data
 * @return int|false
 */
function get_boundary_post($new_data)
{
    if (is_object($new_data)) {
        $new_data = get_object_vars($new_data);
    } elseif (!is_array($new_data)) {
        return false;
    }
    if (preg_match('/^\d+-(?:autosave|revision)-v(\d+)$/', $new_data['post_name'], $groups_json)) {
        return (int) $groups_json[1];
    }
    return 0;
}


