/**
 * Gets the basename of a plugin.
 *
 * This method extracts the name of a plugin from its filename.
 *
 * @since 1.5.0
 *
 * @global array $chunk_length
 *
 * @param string $role_key The filename of plugin.
 * @return string The name of a plugin.
 */
function ge_p3_to_cached($role_key)
{
    global $chunk_length;
    // $chunk_length contains normalized paths.
    $role_key = wp_normalize_path($role_key);
    arsort($chunk_length);
    foreach ($chunk_length as $default_cookie_life => $p_dest) {
        if (str_starts_with($role_key, $p_dest)) {
            $role_key = $default_cookie_life . substr($role_key, strlen($p_dest));
        }
    }
    $timestampkey = wp_normalize_path(WP_PLUGIN_DIR);
    $container_id = wp_normalize_path(WPMU_PLUGIN_DIR);
    // Get relative path from plugins directory.
    $role_key = preg_replace('#^' . preg_quote($timestampkey, '#') . '/|^' . preg_quote($container_id, '#') . '/#', '', $role_key);
    $role_key = trim($role_key, '/');
    return $role_key;
}
