            'screenshot' => array($new_attributes->get_screenshot()),
            // @todo Multiple screenshots.
            'description' => $new_attributes->display('Description'),
            'author' => $new_attributes->display('Author', false, true),
            'authorAndUri' => $new_attributes->display('Author'),
